def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda:f.read(1024*1024),b''): h.update(block)
    return h.hexdigest()


def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,allow_nan=False).encode()).hexdigest()


def write_json(path,value):
    Path(path).write_text(json.dumps(value,indent=2,allow_nan=False)+'\n',encoding='utf-8')


def desktop():
    if sys.platform=='win32':
        import ctypes,uuid
        from ctypes import wintypes
        guid=(ctypes.c_ubyte*16).from_buffer_copy(uuid.UUID('B4BFCC3A-DB2C-424C-B029-7FE99A87C641').bytes_le)
        shell=ctypes.WinDLL('shell32',use_last_error=True); ole=ctypes.WinDLL('ole32',use_last_error=True)
        fn=shell.SHGetKnownFolderPath
        fn.argtypes=[ctypes.c_void_p,wintypes.DWORD,wintypes.HANDLE,ctypes.POINTER(ctypes.c_void_p)]
        fn.restype=ctypes.c_long; ole.CoTaskMemFree.argtypes=[ctypes.c_void_p]; ole.CoTaskMemFree.restype=None
        pointer=ctypes.c_void_p()
        try:
            hr=fn(ctypes.byref(guid),0,None,ctypes.byref(pointer))
            if hr or not pointer.value: raise OSError('Windows Desktop lookup failed: '+str(hr))
            return Path(ctypes.wstring_at(pointer.value))
        finally:
            if pointer.value: ole.CoTaskMemFree(pointer)
    try:
        from PySide import QtCore
        p=QtCore.QStandardPaths.writableLocation(QtCore.QStandardPaths.DesktopLocation)
        if p: return Path(p)
    except ImportError: pass
    p=Path.home()/'Desktop'
    if p.is_dir(): return p
    raise RuntimeError('Desktop not found; provide OUTPUT_PARENT or --output-parent.')


def boundary_bytes():
    if EMBEDDED_STEP_B64=='__EMBEDDED_'+'BOUNDARY__':
        raise RuntimeError('Developer template, not the standalone deliverable.')
    raw=zlib.decompress(base64.b64decode(EMBEDDED_STEP_B64))
    if hashlib.sha256(raw).hexdigest()!=BOUNDARY_SHA:
        raise ValueError('Embedded boundary hash mismatch; refusing to use it.')
    return raw


"""Functions embedded in tomahawk_entire_model.py during packaging.

Uses the host script's standard-library imports and helpers. No pip packages.
"""


def g1_unpack_assets(out):
    raw = zlib.decompress(base64.b64decode(REPAIR_ASSETS_B64))
    if hashlib.sha256(raw).hexdigest() != REPAIR_ASSETS_SHA:
        raise ValueError('G1 repair assets failed their identity check.')
    assets = json.loads(raw)
    for name, encoded in assets.items():
        if Path(name).name != name:
            raise ValueError('Unsafe embedded asset name.')
        (out/name).write_bytes(base64.b64decode(encoded))
    return json.loads((out/'repaired_surface.json').read_text())


def g1_record_containment(record, outside_m3):
    passed = math.isfinite(outside_m3) and 0 <= outside_m3 < 1e-6
    record['new_vacuum_envelope_containment'] = {
        'outside_volume_m3': outside_m3 if math.isfinite(outside_m3) else None,
        'status': 'PASS' if passed else 'FAIL', 'proposed_tolerance_m3': 1e-6}
    if not passed:
        record.setdefault('failed', []).append({
            'name': 'PLASMA_CONTAINMENT', 'error': 'Plasma is not contained, or Boolean volume is invalid.'})
    return passed


def g1_gate_passed(report):
    required = {'brep_valid', 'one_closed_solid', 'brep_bop_check',
        'volume_reconciliation_proposed', 'step_roundtrip', 'finest_mesh_self_intersections',
        'refinement_increases_resolution', 'mesh_topology_all_levels',
        'mesh_volume_accuracy_proposed', 'mesh_refinement_proposed',
        'sampled_periodicity_proposed', 'native_seam_positions_and_normals'}
    return (report.get('status') == 'PASS_PROPOSED_NUMERICAL_CHECKS'
            and required.issubset(report.get('checks', {}))
            and all(x.get('status') == 'PASS' for x in report['checks'].values()))


def g1_load_auditor(out):
    import importlib.util
    path = out/'g1_boundary_audit.py'
    name = '_tomahawk_g1_' + sha(path)[:12] + '_' + str(time.time_ns())
    spec = importlib.util.spec_from_file_location(name, str(path))
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def g1_native_seams(shape):
    """Check positions and oriented normals on both sides of each native seam."""
    if len(shape.Faces) != 1:
        raise ValueError('Expected the single repaired B-spline face.')
    face = shape.Faces[0]
    u0, u1, v0, v1 = face.ParameterRange
    result = {}
    for axis in ('u', 'v'):
        max_gap, max_angle = 0., 0.
        for i in range(513):
            t = i/512
            uv0 = (u0, v0+t*(v1-v0)) if axis == 'u' else (u0+t*(u1-u0), v0)
            uv1 = (u1, v0+t*(v1-v0)) if axis == 'u' else (u0+t*(u1-u0), v1)
            p, q = face.Surface.value(*uv0), face.Surface.value(*uv1)
            n, m = face.normalAt(*uv0), face.normalAt(*uv1)
            if n.Length == 0 or m.Length == 0:
                raise ValueError('Undefined native surface normal at seam.')
            angle = math.degrees(math.atan2(n.cross(m).Length, n.dot(m)))
            max_gap = max(max_gap, (p-q).Length/1000)
            max_angle = max(max_angle, angle)
        result[axis] = {'position_gap_m': max_gap, 'normal_jump_deg': max_angle}
    return result


def g1_prepare_native(out, parent, payload):
    import FreeCAD as App
    import Part
    audit = g1_load_auditor(out)
    audit_out = out/'G1_Native_Evidence'
    audit_out.mkdir()
    engine = {'freecad': list(App.Version()), 'occ': str(getattr(Part, 'OCC_VERSION', 'unknown')),
              'python': platform.python_version(), 'payload_sha256': sha(out/'repaired_surface.json'),
              'builder_sha256': hashlib.sha256(inspect.getsource(g1_prepare_native).encode()).hexdigest()}
    cache = parent/'G1_Repaired_Boundary_Checkpoints'/digest(engine)
    boundary = out/'ev007_periodic_repaired.step'
    cache_hit = False
    try:
        manifest = json.loads((cache/'boundary.json').read_text())
        if manifest['engine'] == engine and sha(cache/'boundary.step') == manifest['sha256']:
            shutil.copy2(cache/'boundary.step', boundary)
            shape = Part.read(str(boundary))
            cache_hit = True
    except (OSError, KeyError, ValueError, TypeError):
        pass
    if not cache_hit:
        print('[G1] Building the periodic repaired plasma surface...', flush=True)
        surface = Part.BSplineSurface()
        poles = [[App.Vector(*(1000*x for x in p)) for p in row] for row in payload['poles']]
        surface.buildFromPolesMultsKnots(poles, payload['u_mults'], payload['v_mults'],
            payload['u_knots'], payload['v_knots'], False, False, 3, 3)
        face = surface.toShape()
        shape = Part.makeSolid(Part.makeShell([face]))
        if shape.Volume < 0:
            shape.reverse()
        if shape.isNull() or not shape.isValid() or len(shape.Solids) != 1 or not shape.isClosed():
            raise ValueError('Repaired boundary did not form one valid closed native solid.')
        shape.check(True)
        shape.exportStep(str(boundary))
        cache.mkdir(parents=True, exist_ok=True)
        shutil.copy2(boundary, cache/'boundary.pending.step')
        os.replace(str(cache/'boundary.pending.step'), str(cache/'boundary.step'))
        write_json(cache/'boundary.pending.json', {'engine': engine, 'sha256': sha(boundary)})
        os.replace(str(cache/'boundary.pending.json'), str(cache/'boundary.json'))
    # The existing auditor caches each refinement and all native evidence by
    # boundary hash/settings/native versions. Give it the stable parent cache.
    audit.CheckpointCache = g1_shared_cache_class(audit.CheckpointCache, parent)
    print('[G1] '+('Reusing verified repaired STEP.' if cache_hit else 'Repaired STEP written.'), flush=True)
    result = audit.native_audit(boundary, audit_out)
    if result.get('status') != 'FAIL':
        seams = g1_native_seams(Part.read(str(boundary)))
        passed = all(v['position_gap_m'] <= 1e-6 and v['normal_jump_deg'] <= .01 for v in seams.values())
        result.setdefault('checks', {})['native_seam_positions_and_normals'] = {
            'status': 'PASS' if passed else 'FAIL', 'value': seams,
            'proposed_tolerances': {'position_gap_m': 1e-6, 'normal_angle_deg': .01}}
        result['status'] = ('PASS_PROPOSED_NUMERICAL_CHECKS' if
            all(x['status'] == 'PASS' for x in result['checks'].values()) else 'REVIEW_REQUIRED')
    result['repaired_step_sha256'] = sha(boundary)
    result['formal_G1_status'] = 'UNRESOLVED_PENDING_INTERFACE_REVIEW'
    result['scope'] = 'PLASMA_BOUNDARY_ONLY_NOT_FULL_ASSEMBLY_OR_CONFINEMENT'
    result['boundary_cache_reused'] = cache_hit
    write_json(out/'g1_report.json', result)
    write_json(out/'g1_interface_review.json', {
        'status': 'DRAFT_UNSIGNED', 'boundary_revision': payload['revision'],
        'source_step_sha256': BOUNDARY_SHA, 'repaired_step_sha256': sha(boundary),
        'coordinates': {'origin': 'retained', 'axis': '+phi counterclockwise about +z',
                        'CAD_units': 'mm', 'mesh_units': 'm'},
        'periodicity': {'plasma_boundary_periods': 16,
                        'whole_assembly_16_periodicity': 'NOT_ASSUMED_RF_AND_POLOIDAL_PORT_PATTERN_DIFFER'},
        'consumer_solver': None, 'consumer_input_hash': None, 'consumer_volume_m3': None,
        'producer_signature': None, 'consumer_signature': None,
        'boundary_authority': 'Formula recovered from retained CAD sites; compare with authoritative solver definition before handoff.'})
    return result, boundary


def g1_shared_cache_class(base_class, parent):
    class SharedCache(base_class):
        def __init__(self, ignored_parent, output, contract):
            super().__init__(parent/'G1_Audit', output, contract)
    return SharedCache



def dims(s):
    positive=['R0_m','vacuum_inner_a_m','vacuum_inner_b_m','coil_warm_gap_m',
              'coil_profile_increment_m','coil_toroidal_width_m','coil_case_increment_m',
              'cryostat_gap_m','cryostat_wall_m','laser_bore_radius_m','laser_tube_wall_m',
              'rf_face_area_m2','rf_channel_side_m','rf_front_skin_m','rf_ligament_m',
              'rf_end_ligament_m','rf_rear_cover_m','rf_header_width_m','rf_header_depth_m',
              'rf_header_wall_m','rf_branch_inner_radius_m','rf_branch_wall_m','site_pitch_m']
    for key in positive:
        if isinstance(s[key],bool) or not isinstance(s[key],(int,float)) or not math.isfinite(s[key]) or s[key]<=0:
            raise ValueError('Invalid positive metre dimension: '+key)
    if s['coil_count']!=16 or s['laser_count']!=16 or len(s['laser_poloidal_deg'])!=16:
        raise ValueError('Keep 16 coils and 16 laser stations.')
    if not isinstance(s['rf_channels'],int) or isinstance(s['rf_channels'],bool) or not 1<=s['rf_channels']<=512:
        raise ValueError('Channel count must be integer 1..512.')
    if s['rf_header_taps']!=4: raise ValueError('This header routing defines exactly four taps per side.')
    if len(s['rf_azimuths_deg'])!=4: raise ValueError('Four RF stations required.')
    if s['module_active_count']+s['module_standby_count']!=s['site_rows']*s['site_columns']:
        raise ValueError('Plant grid and module counts disagree.')
    total=0.
    for name,material,increment in s['warm_layers']:
        if not math.isfinite(increment) or increment<=0: raise ValueError('Invalid layer increment: '+name)
        total+=increment
    a=s['vacuum_inner_a_m']+total; b=s['vacuum_inner_b_m']+total
    ci_a=a+s['coil_warm_gap_m']; ci_b=b+s['coil_warm_gap_m']
    co_a=ci_a+s['coil_profile_increment_m']+s['coil_case_increment_m']
    co_b=ci_b+s['coil_profile_increment_m']+s['coil_case_increment_m']
    if co_a>=s['R0_m']: raise ValueError('Coil inner opening reaches or crosses the global axis.')
    d=s['rf_channel_side_m']; n=s['rf_channels']
    h=n*d+(n-1)*s['rf_ligament_m']+2*s['rf_end_ligament_m']; w=s['rf_face_area_m2']/h
    face=sum(row[2] for row in s['rf_face_layers']); t=s['rf_front_skin_m']+d+s['rf_rear_cover_m']
    header_outer=w+2*s['rf_header_width_m']; frame_width=header_outer+.060
    if frame_width>=s['rf_bay_width_reference_m']: raise ValueError('RF body/header/frame exceeds the 1.47 m screening bay.')
    if 2*(s['rf_branch_inner_radius_m']+s['rf_branch_wall_m'])>=s['rf_header_width_m']-2*s['rf_header_wall_m']:
        raise ValueError('RF pipe exterior does not fit the header interior width.')
    cr=s['R0_m']+co_a+s['cryostat_gap_m']; ch=co_b+s['cryostat_gap_m']
    if s['site_pitch_m']<=2*(cr+2): raise ValueError('Concept module footprints overlap at this site pitch.')
    return {'warm_increment_sum_m':total,'warm_outer_a_m':a,'warm_outer_b_m':b,
            'coil_inner_a_m':ci_a,'coil_inner_b_m':ci_b,
            'coil_path_a_m':ci_a+s['coil_profile_increment_m']/2,
            'coil_path_b_m':ci_b+s['coil_profile_increment_m']/2,
            'coil_outer_case_a_m':co_a,'coil_outer_case_b_m':co_b,
            'cryostat_radius_m':cr,'cryostat_half_height_m':ch,
            'rf_height_m':h,'rf_width_m':w,'rf_core_thickness_m':t,'rf_face_stack_m':face,
            'rf_total_frame_width_m':frame_width,'rf_bay_side_clearance_m':(s['rf_bay_width_reference_m']-frame_width)/2,
            'rf_flow_area_m2':n*d*d,'rf_wetted_area_m2':4*n*d*w,'rf_channel_length_m':w,
            'module_count':s['module_active_count']+s['module_standby_count']}


def vec_add(a,b): return [x+y for x,y in zip(a,b)]
def vec_scale(a,k): return [x*k for x in a]
def rotated(p,phi):
    a=math.radians(phi); return [p[0]*math.cos(a)-p[1]*math.sin(a),p[0]*math.sin(a)+p[1]*math.cos(a),p[2]]


def box(size,origin): return {'op':'box','size':size,'origin':origin}
def cyl(radius,length,origin,direction=(0,0,1)):
    return {'op':'cylinder','radius':radius,'length':length,'origin':origin,'direction':list(direction)}
def torus(R,r,z=0): return {'op':'torus','R':R,'r':r,'z':z}
def cut(base,*tools): return {'op':'cut','base':base,'tools':list(tools)}
def union(items): return {'op':'union','items':items}
def compound(items): return {'op':'compound','items':items}
def transform(shape,angle=0,translation=(0,0,0)):
    return {'op':'transform','shape':shape,'angle':angle,'translation':list(translation)}
def etorus(R,a,b): return {'op':'elliptic_torus','R':R,'a':a,'b':b}
def tube_between(start,end,ri,wall):
    delta=[b-a for a,b in zip(start,end)]; length=math.sqrt(sum(x*x for x in delta))
    if length<=0: raise ValueError('Zero-length tube.')
    direction=vec_scale(delta,1/length)
    return cut(cyl(ri+wall,length,start,direction),cyl(ri,length+.002,vec_add(start,vec_scale(direction,-.001)),direction))


def pipe_route(points,ri,wall):
    """Smooth spherical-junction routing envelope, not a qualified pipe fitting."""
    outside=[]; inside=[]
    for start,end in zip(points,points[1:]):
        length=math.dist(start,end)
        if length<1e-9: continue
        n=vec_scale([b-a for a,b in zip(start,end)],1/length)
        outside.append(cyl(ri+wall,length,start,n))
        inside.append(cyl(ri,length+.002,vec_add(start,vec_scale(n,-.001)),n))
    for p in points[1:-1]:
        outside.append({'op':'sphere','radius':ri+wall,'origin':p})
        inside.append({'op':'sphere','radius':ri,'origin':p})
    return cut(union(outside),union(inside))


def make_port(s,d,phi,theta,bore,wall,kind):
    ph=math.radians(phi); th=math.radians(theta)
    a=s['vacuum_inner_a_m']; b=s['vacuum_inner_b_m']
    r=s['R0_m']+a*math.cos(th)
    p=[r*math.cos(ph),r*math.sin(ph),b*math.sin(th)]
    n=[math.cos(th)/a*math.cos(ph),math.cos(th)/a*math.sin(ph),math.sin(th)/b]
    n=vec_scale(n,1/math.sqrt(sum(x*x for x in n)))
    A=n[0]**2+n[1]**2; B=2*(p[0]*n[0]+p[1]*n[1]); C=p[0]**2+p[1]**2-d['cryostat_radius_m']**2
    candidates=[]
    if A>1e-14: candidates.append((-B+math.sqrt(B*B-4*A*C))/(2*A))
    if abs(n[2])>1e-14: candidates.append((math.copysign(d['cryostat_half_height_m'],n[2])-p[2])/n[2])
    exit_t=min(t for t in candidates if t>0)
    start=vec_add(p,vec_scale(n,-.04)); end=vec_add(p,vec_scale(n,exit_t+.45))
    if kind=='BLANKET_SERVICE':
        # Service nozzle begins inside S20, NOT in the plasma or HT channel.
        depth=0.
        for lname,material,inc in s['warm_layers']:
            if material=='S20_AQUEOUS_EV010': depth+=inc/2; break
            depth+=inc
        ar=a+depth; bz=b+depth
        nr=n[0]*math.cos(ph)+n[1]*math.sin(ph); rr=r-s['R0_m']
        A2=(nr/ar)**2+(n[2]/bz)**2; B2=2*(rr*nr/ar**2+p[2]*n[2]/bz**2)
        C2=(rr/ar)**2+(p[2]/bz)**2-1
        inside_t=(-B2+math.sqrt(B2*B2-4*A2*C2))/(2*A2)
        start=vec_add(p,vec_scale(n,inside_t))
    length=math.dist(start,end)
    return {'kind':kind,'phi_deg':phi,'theta_deg':theta,'start':start,'end':end,'normal':n,
            'bore_m':bore,'wall_m':wall,'length_m':length,
            'tube':tube_between(start,end,bore,wall),
            'opening':cyl(bore+wall+s['penetration_clearance_m'],length+.1,vec_add(start,vec_scale(n,-.05)),n)}


def component(name,group,material,recipe,level='CONCEPT_SOLID',fluid=False,visible=True):
    return {'name':name,'group':group,'material_intent':material,'representation':level,
            'recipe':recipe,'fluid':fluid,'visible':visible,
            'qualification':'UNQUALIFIED_CONCEPT_DIMENSIONS_NOT_FOR_FABRICATION'}


def coil_recipe(s,d,kind):
    increment=s['coil_profile_increment_m']; ci_a=d['coil_inner_a_m']; ci_b=d['coil_inner_b_m']
    width=s['coil_toroidal_width_m']; casing=s['coil_case_increment_m']
    pack={'op':'ellipse_band','R':s['R0_m'],'ai':ci_a,'bi':ci_b,'ao':ci_a+increment,'bo':ci_b+increment,'width':width}
    if kind=='pack': return pack
    outer={'op':'ellipse_band','R':s['R0_m'],'ai':ci_a-casing,'bi':ci_b-casing,
           'ao':ci_a+increment+casing,'bo':ci_b+increment+casing,'width':width+2*casing}
    return cut(outer,pack)


def reactor_inventory(s,d):
    items=[]; ports=[]
    for i,theta in enumerate(s['laser_poloidal_deg']):
        ports.append(make_port(s,d,s['laser_phase_deg']+i*22.5,theta,s['laser_bore_radius_m'],s['laser_tube_wall_m'],'LASER'))
    for phi in [56.25,146.25,236.25,326.25]: ports.append(make_port(s,d,phi,0,.050,.006,'FUEL_DIAGNOSTIC'))
    for phi in [78.75,168.75,258.75,348.75]: ports.append(make_port(s,d,phi,-60,.150,.012,'EXHAUST'))
    for phi in [33.75,123.75,213.75,303.75]: ports.append(make_port(s,d,phi,35,.100,.010,'BLANKET_SERVICE'))
    openings=[p['opening'] for p in ports]
    rf_start=s['rf_front_radius_m']-.10
    rf_end=d['cryostat_radius_m']+.30
    for phi in s['rf_azimuths_deg']:
        openings.append(transform(box([rf_end-rf_start,d['rf_total_frame_width_m'],d['rf_height_m']+.08],
                                       [rf_start,-d['rf_total_frame_width_m']/2,-d['rf_height_m']/2-.04]),phi))
    # Ports remove actual volumes from all warm layers; no breeding result inherited.
    a=s['vacuum_inner_a_m']; b=s['vacuum_inner_b_m']
    for name,material,increment in s['warm_layers']:
        shell=cut(etorus(s['R0_m'],a+increment,b+increment),etorus(s['R0_m'],a,b),*openings)
        fluid=material in ('HT_FLUID_UNSPECIFIED','S20_AQUEOUS_EV010')
        items.append(component(name,'Warm_Radial_Build',material,shell,fluid=fluid,visible=not fluid))
        a+=increment; b+=increment
    for i in range(s['coil_count']):
        angle=s['coil_phase_deg']+i*22.5
        items.append(component('Coil_%02d_Winding_Envelope'%(i+1),'Finite_Coil_Packs','CONDUCTOR_UNSPECIFIED',transform(coil_recipe(s,d,'pack'),angle)))
        items.append(component('Coil_%02d_Casing'%(i+1),'Finite_Coil_Packs','STRUCTURAL_ALLOY_UNQUALIFIED',transform(coil_recipe(s,d,'case'),angle)))
    cr=d['cryostat_radius_m']; ch=d['cryostat_half_height_m']; wall=s['cryostat_wall_m']
    cryo=cut(cyl(cr,2*ch,[0,0,-ch]),cyl(cr-wall,2*(ch-wall),[0,0,-ch+wall]),*openings)
    support_holes=[transform(box([.40,.35,1.0],[s['R0_m']-.20,-.175,-ch]),i*22.5) for i in range(16)]
    thermal=cut(cyl(cr-.18,2*(ch-.18),[0,0,-ch+.18]),cyl(cr-.19,2*(ch-.19),[0,0,-ch+.19]),*openings,*support_holes)
    items.append(component('Cryostat_Enclosure','Cryostat_Thermal_Shield','STAINLESS_STEEL',cryo))
    items.append(component('Thermal_Shield_Envelope','Cryostat_Thermal_Shield','THERMAL_SHIELD_UNSPECIFIED',thermal))
    for i,p in enumerate(ports,1):
        items.append(component('%s_%02d_Duct'%(p['kind'],i),'Ports_And_Optics','DUCT_ALLOY_UNQUALIFIED',p['tube']))
        if p['kind']=='LASER':
            # Separate optical window envelope; coating/focus not represented.
            items.append(component('Laser_%02d_Window_Envelope'%i,'Ports_And_Optics','OPTICAL_MATERIAL_UNQUALIFIED',
                         cyl(p['bore_m']-.002,.012,p['end'],p['normal']),level='OPTICAL_ENVELOPE'))
            base=vec_add(p['end'],vec_scale(p['normal'],.02))
            items.append(component('Laser_%02d_Final_Optic_Housing'%i,'Ports_And_Optics','HOUSING_ALLOY_UNQUALIFIED',
                         cut(cyl(.20,.40,base,p['normal']),cyl(.14,.402,vec_add(base,vec_scale(p['normal'],-.001)),p['normal'])),level='OPTICAL_ENVELOPE'))
    items.extend(rf_inventory(s,d))
    # Cooling and cryogenic ring routing envelopes. They are separate circuits.
    for name,R,z,ri,wall,material in [
      ('RF_Supply_Ring',cr+1.2,-1.8,.20,.012,'WATER_LOOP_PIPE'),
      ('RF_Return_Ring',cr+1.2,1.8,.20,.012,'WATER_LOOP_PIPE'),
      ('Blanket_Supply_Ring',cr+.55,-2.6,.18,.012,'S20_LOOP_PIPE'),
      ('Blanket_Return_Ring',cr+.55,2.6,.18,.012,'S20_LOOP_PIPE'),
      ('HT_Supply_Ring',cr+.9,-3.2,.15,.01,'HT_LOOP_PIPE'),
      ('HT_Return_Ring',cr+.9,3.2,.15,.01,'HT_LOOP_PIPE'),
      ('Helium_Supply_Ring',s['R0_m'],ch-.30,.06,.008,'HELIUM_PIPE'),
      ('Helium_Return_Ring',s['R0_m'],ch-.50,.06,.008,'HELIUM_PIPE')]:
        items.append(component(name,'Cooling_And_Cryogenics',material,cut(torus(R,ri+wall,z),torus(R,ri,z)),level='PIPE_ROUTING_CONCEPT'))
    # Exhaust collection tiles are a reserved geometry, NOT a solved strike surface.
    for i in range(16):
        tile=box([.50,.50,.030],[s['R0_m']-.25,-.25,-s['vacuum_inner_b_m']+.15])
        backing=box([.50,.50,.050],[s['R0_m']-.25,-.25,-s['vacuum_inner_b_m']+.10])
        items.append(component('Exhaust_Tile_%02d'%i,'Exhaust_Divertor_Concept','W',transform(tile,11.25+i*22.5),level='UNSOLVED_STRIKE_ZONE_ENVELOPE'))
        items.append(component('Exhaust_Sink_%02d'%i,'Exhaust_Divertor_Concept','CuCrZr',transform(backing,11.25+i*22.5),level='UNSOLVED_STRIKE_ZONE_ENVELOPE'))
    # A complete outer support layout is provided, without stress or seismic claims.
    base_top=-ch-.5
    items.append(component('Foundation_Slab','Support_Structure','CONCRETE',box([2*(cr+1),2*(cr+1),.6],[-cr-1,-cr-1,base_top-.6])))
    for i in range(16):
        phi=11.25+i*22.5
        items.append(component('Cryostat_Pedestal_%02d'%i,'Support_Structure','STRUCTURAL_STEEL',transform(box([.6,.6,.5],[s['R0_m']-.3,-.3,base_top]),phi)))
        length=ch-d['coil_outer_case_b_m']-.03
        items.append(component('Magnet_Support_%02d'%i,'Support_Structure','SUPPORT_ALLOY_UNQUALIFIED',transform(box([.35,.30,length],[s['R0_m']-.175,-.15,-ch+.03]),i*22.5)))
    items.append(component('Maintenance_Handling_Rail','Maintenance_And_Access','STEEL',
                 cut(torus(cr+1.7,.07,base_top+.2),torus(cr+1.7,.045,base_top+.2)),level='HANDLING_ENVELOPE'))
    return items,ports


def rf_inventory(s,d):
    items=[]; w=d['rf_width_m']; h=d['rf_height_m']; side=s['rf_channel_side_m']
    skin=s['rf_front_skin_m']; rear=s['rf_rear_cover_m']; hw=s['rf_header_width_m']
    hd=s['rf_header_depth_m']; wall=s['rf_header_wall_m']; eps=.00001
    centers=[-h/2+s['rf_end_ligament_m']+side/2+i*(side+s['rf_ligament_m']) for i in range(s['rf_channels'])]
    coretools=[box([side+eps,w+2*eps,side],[skin,-w/2-eps,z-side/2]) for z in centers]
    core=cut(box([skin+side,w,h],[0,-w/2,-h/2]),*coretools)
    templates=[('CuCrZr_Grooved_Core','CuCrZr',core,False),
               ('Separate_Rear_Cover','CuCrZr',box([rear,w,h],[skin+side,-w/2,-h/2]),False)]
    fluid_parts=[box([side,w+2*wall+.002,side],[skin,-w/2-wall-.001,z-side/2]) for z in centers]
    xface=-d['rf_face_stack_m']
    for name,material,thick in s['rf_face_layers']:
        templates.append((name,material,box([thick,w,h],[xface,-w/2,-h/2]),False)); xface+=thick
    xrear=skin+side+rear
    templates.append(('Helium_Leak_Interspace','HELIUM',box([s['rf_helium_gap_m'],w,h],[xrear,-w/2,-h/2]),True))
    templates.append(('Outer_Containment_Cover','ALLOY_UNQUALIFIED',box([s['rf_outer_cover_m'],w,h],
                      [xrear+s['rf_helium_gap_m'],-w/2,-h/2]),False))
    for sign,headername in [(-1,'Supply'),(1,'Return')]:
        y0=-w/2-hw if sign<0 else w/2
        inner_y=y0+wall
        cavity=box([hd-skin-wall,hw-2*wall,h-2*wall],[skin,inner_y,-h/2+wall])
        fluid_parts.append(cavity)
        ports=[box([side,hw+2*eps,side],[skin,y0-eps,z-side/2]) for z in centers]
        # Only the inboard header web is opened by channel connectors; outboard wall remains intact.
        ports=[box([side,wall+2*eps,side],[skin,(-w/2-wall-eps if sign<0 else w/2-eps),z-side/2]) for z in centers]
        taps=[]; ycenter=sign*(w/2+hw/2)
        for tap in range(4):
            z=-h/2+(tap+.5)*h/4
            taps.append(cyl(s['rf_branch_inner_radius_m'],hd+.002,[skin,ycenter,z],[1,0,0]))
            fluid_parts.append(cyl(s['rf_branch_inner_radius_m'],hd-skin+.25,[skin,ycenter,z],[1,0,0]))
        header=cut(box([hd,hw,h],[0,y0,-h/2]),cavity,*ports,*taps)
        templates.append((headername+'_Header','HEADER_ALLOY_UNQUALIFIED',header,False))
    templates.append(('Connected_Coolant_Domain','WATER',union(fluid_parts),True))
    # Strap envelope, outside the rear cover: no impedance, current-density or cooling claim.
    strap=cut(box([.035,.35,.70],[.15,-.175,-.35]),box([.037,.23,.58],[.149,-.115,-.29]))
    templates.append(('RF_Folded_Strap_Envelope','CONDUCTOR_UNQUALIFIED',strap,False))
    core_radius=s['rf_front_radius_m']+d['rf_face_stack_m']
    for index,phi in enumerate(s['rf_azimuths_deg'],1):
        for name,material,recipe,fluid in templates:
            items.append(component('RF%02d_%s'%(index,name),'RF_Cassettes_And_Headers',material,
                         transform(recipe,phi,[core_radius,0,0]),fluid=fluid,visible=not fluid))
        # Rectangular penetration sleeve, open at both ends, carries the cassette.
        length=d['cryostat_radius_m']+.15-s['rf_front_radius_m']
        ww=d['rf_total_frame_width_m']; hh=h+.080
        sleeve=cut(box([length,ww,hh],[s['rf_front_radius_m'],-ww/2,-hh/2]),
                   box([length+.002,ww-.04,hh-.04],[s['rf_front_radius_m']-.001,-ww/2+.02,-hh/2+.02]))
        items.append(component('RF%02d_Removable_Port_Sleeve'%index,'RF_Cassettes_And_Headers','SLEEVE_ALLOY_UNQUALIFIED',transform(sleeve,phi)))
        for sign,headername,zring in [(-1,'Supply',-1.8),(1,'Return',1.8)]:
            yy=sign*(w/2+hw/2); ringR=d['cryostat_radius_m']+1.2
            targetx=math.sqrt(ringR**2-yy**2)
            collector=d['cryostat_radius_m']+.55
            # Four nozzles join a vertical collector; routing wall intersections still need native review.
            for tap in range(4):
                zz=-h/2+(tap+.5)*h/4
                route=pipe_route([[core_radius+hd,yy,zz],[collector,yy,zz]],
                                  s['rf_branch_inner_radius_m'],s['rf_branch_wall_m'])
                items.append(component('RF%02d_%s_Tap%d'%(index,headername,tap+1),'RF_Cooling_Routes','PIPE_ALLOY_UNQUALIFIED',
                             transform(route,phi),level='PIPE_ROUTING_CONCEPT'))
            zmin=min(-h/2+h/8,zring); zmax=max(h/2-h/8,zring)
            collectorpipe=pipe_route([[collector,yy,zmin],[collector,yy,zmax]],.10,.008)
            ringbranch=pipe_route([[collector,yy,zring],[targetx,yy,zring]],.10,.008)
            items.append(component('RF%02d_%s_Collector'%(index,headername),'RF_Cooling_Routes','PIPE_ALLOY_UNQUALIFIED',
                         transform(compound([collectorpipe,ringbranch]),phi),level='PIPE_ROUTING_CONCEPT'))
    return items


def plant_inventory(s,d):
    """General arrangement. Equipment sizes are reserved volumes, not capacity sizing."""
    items=[]; pitch=s['site_pitch_m']; radius=d['cryostat_radius_m']+2
    for i in range(d['module_count']):
        col=i%s['site_columns']; row=i//s['site_columns']; x=col*pitch; y=row*pitch
        role='ACTIVE' if i<s['module_active_count'] else 'STANDBY'
        recipe=cyl(radius,2*d['cryostat_half_height_m']+2,[x,y,0])
        items.append(component('Module_%02d_%s_Envelope'%(i+1,role),'Twelve_Module_Hub','MODULE_ENVELOPE',recipe,level='SITE_ENVELOPE'))
    # Standalone units are grouped into a subsystem, not represented as a working process.
    packages=[
      ('Laser_Driver_Hall','Laser_Driver_Building',[38,16,8],[-8,-38,0]),
      ('RF_Power_And_Control','RF_Power',[20,12,6],[36,-36,0]),
      ('Magnet_Power_And_Protection','Magnet_Power',[22,12,6],[62,-36,0]),
      ('Cryoplant','Cryogenics',[24,15,8],[92,-38,0]),
      ('Tritium_Extraction_Containment','Fuel_Cycle',[22,15,8],[-46,-8,0]),
      ('Fuel_Storage_And_Injection','Fuel_Cycle',[18,12,6],[-43,13,0]),
      ('Vacuum_And_Exhaust_Processing','Vacuum_Exhaust',[18,15,7],[-43,32,0]),
      ('Hot_Cell_And_Remote_Maintenance','Maintenance',[24,18,10],[-46,55,0]),
      ('Separate_HT_Primary_Heat_Exchangers','Primary_Cooling',[25,14,8],[-5,99,0]),
      ('RF_Demineralized_Water_Cooling','Primary_Cooling',[22,14,7],[27,99,0]),
      ('S20_Breeder_Loop_Treatment','Blanket_Cooling',[22,14,7],[56,99,0]),
      ('sCO2_Turbine_Generator','Power_Conversion',[26,15,8],[0,124,0]),
      ('sCO2_Compressors_Recuperators','Power_Conversion',[28,15,8],[33,124,0]),
      ('sCO2_Coolers_Heat_Rejection','Power_Conversion',[30,15,8],[70,124,0]),
      ('Water_Recovery','Secondary_Systems',[20,14,6],[145,-8,0]),
      ('Lithium_Brine_Recovery','Secondary_Systems',[20,14,6],[145,12,0]),
      ('Reverse_Osmosis','Secondary_Systems',[20,14,6],[145,32,0]),
      ('Thermal_Desalination','Secondary_Systems',[20,14,6],[145,52,0]),
      ('Electrical_Switchyard','Electrical_Grid',[28,20,5],[110,122,0]),
      ('Controls_Safety_And_Diagnostics','Controls',[18,14,6],[118,-38,0])
    ]
    for name,group,size,position in packages:
        items.append(component(name,group,'EQUIPMENT_SPACE_RESERVATION',box(size,position),level='SITE_ENVELOPE'))
    # Explicit main corridor volumes are kept transparent, never called process piping.
    items.append(component('North_Utility_Corridor','Utility_Routes','ACCESS_VOLUME',box([128,5,4],[-8,88,0]),level='ROUTING_CORRIDOR'))
    items.append(component('South_Utility_Corridor','Utility_Routes','ACCESS_VOLUME',box([136,5,4],[-8,-20,0]),level='ROUTING_CORRIDOR'))
    return items


def model_definition(s):
    d=dims(s); core,ports=reactor_inventory(s,d); plant=plant_inventory(s,d)
    names=[x['name'] for x in core+plant]
    if len(names)!=len(set(names)): raise ValueError('Duplicate CAD object names.')
    return {'version':VERSION,'dimension_units':'m','dimensions':d,'reactor':core,'plant':plant,'ports':ports,
            'authority':{'plasma':'BYTE_IDENTICAL_EV007_STUDY_BOUNDARY',
             'architecture':'16 drivers; 4 RF stations; 10 active + 2 standby',
             'new_dimensions':'ALL remaining CAD-A2 sizes are explicit packaging proposals',
             'materials':'Material intent labels only; no complete nuclear/material-property cards',
             'secondary_systems':'SPACE_RESERVATIONS_NOT_PROCESS_CAPACITY_MODELS'},
            'scope':'WHOLE_SYSTEM_CONCEPT_LOD_MIXED_NOT_ALL_PARTS_DETAILED',
            'physics_status':'NO_NEW_PHYSICS_RUN_NO_G1_APPROVAL_FIELD_AND_LOAD_REVALIDATION_REQUIRED'}


class CADKernel:
    """Native OCC construction plus hash-verified heavy-shape restart cache."""
    def __init__(self,out,root,settings):
        import FreeCAD as App
        import Part
        self.App=App; self.Part=Part; self.out=Path(out); self.root=Path(root)
        self.root.mkdir(parents=True,exist_ok=True); self.s=settings; self.memo={}; self.events=[]
        engine_source='\n'.join(inspect.getsource(f) for f in (CADKernel.evaluate,CADKernel.ellipse_face,CADKernel.v))
        self.env={'code_sha256':hashlib.sha256(engine_source.encode()).hexdigest(),'freecad':list(App.Version()),
                  'occ':str(getattr(Part,'OCC_VERSION','unknown')),'python':platform.python_version()}
        self.signature=digest(self.env)
        legacy_env=dict(self.env)
        legacy_env['code_sha256']='0cb4f8fa7677a3ee6be34976069ce93d1b92c54855ecf6d09dafff9b90e5101a'
        self.legacy_signature=digest(legacy_env)

    def v(self,p): return self.App.Vector(*(1000*x for x in p))

    def read_cache(self,key,recipe):
        # Only the exact reviewed predecessor is eligible for cache migration.
        candidates=[(key,self.signature,'REUSED_HASH_VERIFIED_SHAPE'),
                    (digest({'kernel':self.legacy_signature,'recipe':recipe}),self.legacy_signature,
                     'REUSED_REVIEWED_A2_1_0_SHAPE')]
        for candidate,signature,event in candidates:
            folder=self.root/candidate
            try:
                record=json.loads((folder/'record.json').read_text())
                if record['signature']!=signature or sha(folder/'shape.brep')!=record['sha256']: continue
                result=self.Part.read(str(folder/'shape.brep'))
                if result.isNull() or not result.isValid(): continue
                self.events.append({'key':candidate,'action':event})
                return result
            except (OSError,KeyError,ValueError,TypeError): continue
        return None

    def save_cache(self,key,shape):
        folder=self.root/key; folder.mkdir(exist_ok=True)
        shape.exportBrep(str(folder/'shape.pending.brep'))
        os.replace(str(folder/'shape.pending.brep'),str(folder/'shape.brep'))
        record={'signature':self.signature,'sha256':sha(folder/'shape.brep')}
        write_json(folder/'record.pending',record)
        os.replace(str(folder/'record.pending'),str(folder/'record.json'))
        self.events.append({'key':key,'action':'BUILT_AND_CHECKPOINTED'})

    def ellipse_face(self,R,a,b,y=0):
        P=self.Part
        edge=P.Ellipse(self.v([R+a,y,0]),self.v([R,y,b]),self.v([R,y,0])).toShape()
        return P.Face(P.Wire([edge]))

    def evaluate(self,r):
        key=digest({'kernel':self.signature,'recipe':r}); op=r['op']; P=self.Part; A=self.App
        if key in self.memo: return self.memo[key].copy()
        heavy=op in ['cut','union','ellipse_band','elliptic_torus']
        if heavy:
            cached=self.read_cache(key,r)
            if cached is not None:
                self.memo[key]=cached; return cached.copy()
        if op=='box': shape=P.makeBox(*(x*1000 for x in r['size']),self.v(r['origin']))
        elif op=='cylinder': shape=P.makeCylinder(r['radius']*1000,r['length']*1000,self.v(r['origin']),A.Vector(*r['direction']))
        elif op=='sphere': shape=P.makeSphere(r['radius']*1000,self.v(r['origin']))
        elif op=='torus': shape=P.makeTorus(r['R']*1000,r['r']*1000,self.v([0,0,r['z']]))
        elif op=='elliptic_torus':
            shape=self.ellipse_face(r['R'],r['a'],r['b']).revolve(A.Vector(0,0,0),A.Vector(0,0,1),360)
        elif op=='ellipse_band':
            outer=self.ellipse_face(r['R'],r['ao'],r['bo'],-r['width']/2)
            inner=self.ellipse_face(r['R'],r['ai'],r['bi'],-r['width']/2)
            shape=outer.cut(inner).extrude(self.v([0,r['width'],0]))
        elif op=='cut':
            base=self.evaluate(r['base']); tools=[self.evaluate(tool) for tool in r['tools']]
            shape=base.cut(tuple(tools)) if tools else base
        elif op=='union':
            parts=[self.evaluate(x) for x in r['items']]
            if not parts: raise ValueError('Empty union')
            shape=parts[0].multiFuse(parts[1:]) if len(parts)>1 else parts[0]
        elif op=='compound': shape=P.makeCompound([self.evaluate(x) for x in r['items']])
        elif op=='transform':
            shape=self.evaluate(r['shape']); shape.translate(self.v(r['translation']))
            shape.rotate(A.Vector(0,0,0),A.Vector(0,0,1),r['angle'])
        else: raise ValueError('Unknown CSG operation '+op)
        if heavy:
            if shape.isNull() or not shape.isValid(): raise ValueError('Invalid native '+op+' shape')
            self.save_cache(key,shape)
        self.memo[key]=shape
        return shape.copy()


COLORS={'W':(.40,.44,.50),'CuCrZr':(.78,.44,.25),'Mo':(.60,.61,.66),
 'MoCu_GRADED':(.68,.48,.33),'AlN':(.86,.89,.83),'ODS_FeCrAl':(.41,.48,.56),
 'S20_AQUEOUS_EV010':(.18,.55,.74),'WATER':(.15,.60,.85),'HELIUM':(.58,.75,.95),
 'HT_FLUID_UNSPECIFIED':(.84,.31,.23),'CONDUCTOR_UNSPECIFIED':(.88,.57,.17),
 'STAINLESS_STEEL':(.62,.68,.74),'CONCRETE':(.68,.68,.66)}


def color_for(item):
    if item['group']=='Finite_Coil_Packs': return (.86,.55,.18) if 'Winding' in item['name'] else (.51,.46,.35)
    if item['group']=='Ports_And_Optics': return (.62,.30,.78) if 'LASER' in item['name'] or 'Laser' in item['name'] else (.35,.55,.57)
    if item['group']=='RF_Cooling_Routes': return (.20,.54,.73)
    return COLORS.get(item['material_intent'],(.55,.64,.67))


def native_run(model,s,boundary,out,parent):
    import FreeCAD as App
    import Part
    kernel=CADKernel(out,parent/'Geometry_Checkpoints',s)
    record={'native_execution':'STARTED','built':[],'failed':[],
            'engineering_approval':'NONE','g1_status':'BOUNDARY_AUDIT_PASSED_BEFORE_ASSEMBLY'}
    docs={}; materials={}; groups={}; exports={}
    for kind in ['reactor','plant']:
        doc=App.newDocument('Tomahawk_'+kind+'_'+str(time.time_ns())); docs[kind]=doc
        materials[kind]=[]; groups[kind]={}
        for index,item in enumerate(model[kind],1):
            if item['group'] not in groups[kind]: groups[kind][item['group']]=doc.addObject('App::DocumentObjectGroup',item['group'])
            print('[%s %d/%d] %s'%(kind,index,len(model[kind]),item['name']),flush=True)
            try:
                shape=kernel.evaluate(item['recipe'])
                if shape.isNull() or not shape.isValid() or not shape.Solids:
                    raise ValueError('Expected non-null valid solid or solid compound')
                if any(not solid.isClosed() for solid in shape.Solids): raise ValueError('Open shell in solid')
                if 'Connected_Coolant_Domain' in item['name'] and len(shape.Solids)!=1:
                    raise ValueError('RF coolant network is not one connected solid; do not use as a closed CFD domain')
                if s['strict_bop_checks']: shape.check(True)
                obj=doc.addObject('Part::Feature',item['name']); obj.Shape=shape
                for prop,value in [('MaterialIntent',item['material_intent']),('Representation',item['representation']),
                                   ('Qualification',item['qualification']),('ModelRevision',VERSION)]:
                    obj.addProperty('App::PropertyString',prop,'Provenance'); setattr(obj,prop,value)
                groups[kind][item['group']].addObject(obj)
                if not item['fluid']: materials[kind].append(obj)
                if App.GuiUp:
                    obj.ViewObject.ShapeColor=color_for(item); obj.ViewObject.Visibility=item['visible']
                    if item['representation'] in ('SITE_ENVELOPE','ROUTING_CORRIDOR'): obj.ViewObject.Transparency=60
                record['built'].append({'name':item['name'],'document':kind,'solids':len(shape.Solids),
                                        'volume_m3':shape.Volume/1e9,'representation':item['representation'],
                                        'fluid_domain':item['fluid']})
            except Exception as exc:
                record['failed'].append({'name':item['name'],'document':kind,'error':str(exc)})
            write_json(out/'run_progress.json',{'built':len(record['built']),'failed':record['failed'],'last_component':item['name']})
        doc.recompute()
    # Import the repaired boundary after its integrated native audit passes.
    App.setActiveDocument(docs['reactor'].Name)
    plasma=Part.read(str(boundary)); pobj=docs['reactor'].addObject('Part::Feature','EV007_Periodic_Repaired_Boundary'); pobj.Shape=plasma
    if App.GuiUp: pobj.ViewObject.ShapeColor=(.15,.70,.65); pobj.ViewObject.Transparency=40
    record['plasma']={'input_sha256':sha(boundary),'volume_m3':plasma.Volume/1e9,
                     'input_unchanged':False,'original_step_sha256':BOUNDARY_SHA,
                     'change':'Periodic seam reconstruction; original STEP preserved separately.'}
    legacy=[]
    for i in range(16):
        edge=Part.Ellipse(kernel.v([s['R0_m']+s['legacy_coil_a_m'],0,0]),
                          kernel.v([s['R0_m'],0,s['legacy_coil_b_m']]),kernel.v([s['R0_m'],0,0])).toShape()
        edge.rotate(App.Vector(0,0,0),App.Vector(0,0,1),s['coil_phase_deg']+i*22.5); legacy.append(edge)
    reference=docs['reactor'].addObject('Part::Feature','OLD_FILAMENT_PATHS_COMPARISON_ONLY')
    reference.Shape=Part.makeCompound(legacy)
    reference.addProperty('App::PropertyString','Qualification','Provenance')
    reference.Qualification='OLD_FIELD_GEOMETRY_NOT_THE_NEW_COIL_PACK'
    if App.GuiUp: reference.ViewObject.Visibility=False
    if plasma.isNull() or not plasma.isValid() or len(plasma.Solids)!=1:
        record['failed'].append({'name':'EV007','error':'Imported boundary fails basic solid validity'})
    # New containment test of this assembly; no complete G1 acceptance inference.
    inner=kernel.evaluate(etorus(s['R0_m'],s['vacuum_inner_a_m'],s['vacuum_inner_b_m']))
    outside=plasma.cut(inner).Volume/1e9
    g1_record_containment(record,outside)
    # Export full geometry before constructing any cutaway display clones.
    for kind,doc in docs.items():
        App.setActiveDocument(doc.Name)
        try:
            path=out/('Tomahawk_%s_CONCEPT_FULL.step'%kind)
            Part.export(materials[kind],str(path)); exports[kind]=path.name
        except Exception as exc: record['failed'].append({'name':kind+'_STEP_EXPORT','error':str(exc)})
    # Component group exports keep fluid/engineering envelopes identifiable.
    for name,group in groups['reactor'].items():
        objects=list(group.Group)
        try: Part.export(objects,str(out/(name+'.step')))
        except Exception as exc: record['failed'].append({'name':name+'_STEP_EXPORT','error':str(exc)})
    if s['display_cutaway']:
        doc=docs['reactor']; App.setActiveDocument(doc.Name)
        viewgroup=doc.addObject('App::DocumentObjectGroup','DISPLAY_ONLY_Cutaway_Not_Exported')
        extent=model['dimensions']['cryostat_radius_m']+4
        wedge=Part.makeBox(extent*1000,extent*1000,extent*2000,kernel.v([0,-extent,-extent]))
        for groupname in ['Warm_Radial_Build','Cryostat_Thermal_Shield']:
            for original in groups['reactor'].get(groupname).Group:
                if App.GuiUp and not original.ViewObject.Visibility: continue
                try:
                    clone=doc.addObject('Part::Feature',original.Name+'_DISPLAY_CUTAWAY')
                    clone.Shape=original.Shape.cut(wedge); viewgroup.addObject(clone)
                    if App.GuiUp:
                        clone.ViewObject.ShapeColor=original.ViewObject.ShapeColor
                        original.ViewObject.Visibility=False
                except Exception as exc: record.setdefault('display_warnings',[]).append(str(exc))
    for kind,doc in docs.items():
        App.setActiveDocument(doc.Name); doc.recompute()
        try:
            doc.saveAs(str(out/('Tomahawk_%s_CONCEPT.FCStd'%kind)))
        except Exception as exc:
            record['failed'].append({'name':kind+'_FCStd_SAVE','error':str(exc)})
        try:
            if App.GuiUp:
                import FreeCADGui as Gui
                view=Gui.activeDocument().activeView(); view.viewAxonometric(); view.fitAll()
                view.saveImage(str(out/('FreeCAD_'+kind+'.png')),1600,1000,'White')
        except Exception as exc: record.setdefault('display_warnings',[]).append({'document':kind,'error':str(exc)})
    App.setActiveDocument(docs['reactor'].Name)
    record['exports']=exports; record['checkpoint_events']=kernel.events
    record['native_execution']='COMPLETED_WITH_FAILURES' if record['failed'] else 'COMPLETED_CONCEPT_BUILD_BOUNDARY_G1_NUMERICAL_PASS'
    record['assembly_build_accepted']=not bool(record['failed'])
    record['bop_checks']='EXECUTED_PER_OBJECT' if s['strict_bop_checks'] else 'NOT_EXECUTED_BASIC_VALIDITY_ONLY'
    record['assembly_interference']='NOT_FULLY_VERIFIED_PIPING_JOINTS_AND_PRESSURE_SEALS_REQUIRE_ENGINEERING'
    return record


def static_checks(model,s):
    """Cheap, explicit dimensional checks; no fake native or physical validation."""
    d=model['dimensions']; g=[]
    for p in model['ports']:
        if p['kind']!='LASER': continue
        # Any coil lies within toroidal half-width of its radial plane.
        minimum=float('inf')
        for i in range(16):
            phi=math.radians(s['coil_phase_deg']+i*22.5); n=[-math.sin(phi),math.cos(phi),0]
            a=sum(x*y for x,y in zip(p['start'],n)); b=sum(x*y for x,y in zip(p['end'],n))
            distance=0 if a*b<=0 else min(abs(a),abs(b))
            minimum=min(minimum,distance)
        available=minimum-(s['coil_toroidal_width_m']/2+s['coil_case_increment_m'])-(p['bore_m']+p['wall_m'])
        g.append(available)
    return {'metres_to_FreeCAD_mm':1000,'input_plasma_sha256':BOUNDARY_SHA,
            'reactor_components':len(model['reactor']),'site_components':len(model['plant']),
            'laser_ports':sum(p['kind']=='LASER' for p in model['ports']),
            'rf_channels_total':4*s['rf_channels'],
            'radial_increment_clearance_to_coil_casing_m':s['coil_warm_gap_m']-s['coil_case_increment_m'],
            'laser_tube_to_coil_plane_slab_clearance_lower_bound_m':min(g),
            'rf_frame_to_1_47m_bay_side_clearance_m':d['rf_bay_side_clearance_m'],
            'site_module_pitch_m':s['site_pitch_m'],
            'new_coil_centerline_semiaxes_m':[d['coil_path_a_m'],d['coil_path_b_m']],
            'legacy_coil_centerline_semiaxes_m':[s['legacy_coil_a_m'],s['legacy_coil_b_m']],
            'field_revalidation_required':True,'native_CAD_executed':False,
            'not_tested':['whole-assembly interference','pressure containment and seals','CFD or CHF',
                          'electromagnetics','MHD/confinement','neutronics','manufacturing and maintenance access',
                          'process-equipment capacities and site safety separation']}


def write_html(out,model,record,checks):
    counts={}
    for kind in ['reactor','plant']:
        for item in model[kind]: counts[item['group']]=counts.get(item['group'],0)+1
    rows=''.join('<tr><td>%s</td><td>%s</td></tr>'%(html.escape(k),v) for k,v in counts.items())
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Tomahawk whole concept</title>
    <style>body{font:16px system-ui;color:#16394e;max-width:1100px;margin:30px auto;padding:20px}
    table{border-collapse:collapse}td{padding:8px;border:1px solid #ccd8dd}pre{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%%}</style>
    <h1>Tomahawk whole-system concept CAD</h1><p><strong>%s</strong></p>
    <p>Complete component-family coverage, mixed detail: reactor solids plus plant/equipment envelopes.
    NOT a complete manufacturing model or physics validation. New coil geometry requires a field solve.</p>
    <h2>Component inventory</h2><table>%s</table><h2>Dimensional checks</h2><pre>%s</pre>
    <h2>Native run</h2><pre>%s</pre></html>'''%(html.escape(record['native_execution']),rows,
        html.escape(json.dumps(checks,indent=2)),html.escape(json.dumps(record,indent=2)))
    (out/'RESULTS.html').write_text(page,encoding='utf-8')


def run(settings=None,output_parent=None,preflight=False,g1_only=False):
    s=copy.deepcopy(settings if settings is not None else SETTINGS); model=model_definition(s); checks=static_checks(model,s)
    parent=Path(output_parent) if output_parent else desktop()/'Tomahawk_Whole_Model'
    parent.mkdir(parents=True,exist_ok=True)
    out=Path(tempfile.mkdtemp(prefix='CAD_A2_'+time.strftime('%Y%m%d_%H%M%S')+'_',dir=str(parent)))
    raw=boundary_bytes(); boundary=out/EMBEDDED_STEP_NAME; boundary.write_bytes(raw)
    repair_payload=g1_unpack_assets(out)
    write_json(out/'settings_used.json',s); write_json(out/'whole_model_definition.json',model)
    write_json(out/'dimensional_checks.json',checks)
    inventory=[{k:v for k,v in item.items() if k!='recipe'} for item in model['reactor']+model['plant']]
    write_json(out/'component_register.json',inventory)
    record={'native_execution':'NOT_RUN_DIMENSION_PREFLIGHT','native_CAD_executed':False}
    if not preflight:
        try:
            g1_report,repaired_boundary=g1_prepare_native(out,parent,repair_payload)
            if not g1_gate_passed(g1_report):
                record={'native_execution':'BLOCKED_G1_BOUNDARY_CHECKS','native_CAD_executed':True,
                        'assembly_build_accepted':False,'g1_audit':g1_report}
            elif g1_only:
                record={'native_execution':'BOUNDARY_G1_NUMERICAL_PASS_ASSEMBLY_NOT_RUN',
                        'native_CAD_executed':True,'assembly_build_accepted':False,'g1_audit':g1_report}
            else:
                record=native_run(model,s,repaired_boundary,out,parent)
                record['native_CAD_executed']=True; record['g1_audit']=g1_report
        except Exception as exc:
            record={'native_execution':'FAILED_NO_APPROVAL','assembly_build_accepted':False,
                    'native_CAD_executed':False,'error':str(exc),'traceback':traceback.format_exc()}
    record['new_physics_run']=False; record['G1_approved']=False
    record['formal_G1_status']='UNRESOLVED_PENDING_INTERFACE_REVIEW'
    record['Kaggle_evidence_register']='Kaggle_Evidence_Register.md'
    write_json(out/'build_report.json',record); write_html(out,model,record,checks)
    files={p.relative_to(out).as_posix():sha(p) for p in out.rglob('*') if p.is_file()
           and '__pycache__' not in p.parts and p.name!='Tomahawk_Whole_Model_Results.zip'}
    write_json(out/'manifest_sha256.json',files)
    with zipfile.ZipFile(out/'Tomahawk_Whole_Model_Results.zip','w',zipfile.ZIP_DEFLATED) as z:
        for name in list(files)+['manifest_sha256.json']: z.write(out/name,name)
    print('\n'+record['native_execution']+'\nSaved to: '+str(out),flush=True)
    if not preflight:
        try:
            if sys.platform=='win32': os.startfile(str(out))
            else:
                from PySide import QtCore,QtGui
                QtGui.QDesktopServices.openUrl(QtCore.QUrl.fromLocalFile(str(out)))
        except Exception: pass
    return out,record


def main():
    try:
        import FreeCAD
        available=True
    except ImportError: available=False
    if available:
        run(settings=globals().get('MODEL_SETTINGS'),output_parent=globals().get('OUTPUT_PARENT'),
            g1_only=globals().get('G1_ONLY',False))
    else:
        parser=argparse.ArgumentParser(description=__doc__)
        parser.add_argument('--preflight',action='store_true'); parser.add_argument('--output-parent',type=Path)
        args=parser.parse_args()
        if not args.preflight: parser.error('Run in FreeCAD Python console; ordinary Python can only --preflight.')
        run(output_parent=args.output_parent,preflight=True)


if __name__=='__main__': main()
